 /** Complete record value comparison includes every nested byte view, not wrapper reference equality. */
 private static Object value(Object o){
  if(o==null)return "<absent>";if(o instanceof CdAssetBytes b)return java.util.HexFormat.of().formatHex(b.copy());
  if(o instanceof Optional<?> x)return x.isPresent()?List.of("present",value(x.orElseThrow())):List.of("empty");
  if(o instanceof List<?> x)return x.stream().map(TestSonicCdAct3FutureOldProgrammeExit::value).toList();
  if(o instanceof byte[] x)return java.util.HexFormat.of().formatHex(x);if(o instanceof int[] x)return Arrays.toString(x);
  if(o.getClass().isRecord()){var all=new ArrayList<Object>();all.add(o.getClass());for(var c:o.getClass().getRecordComponents())try{var m=c.getAccessor();m.setAccessible(true);all.add(List.of(c.getName(),value(m.invoke(o))));}catch(ReflectiveOperationException e){throw new AssertionError(e);}return all;}
  return o;
 }
